// import axios from "axios";
// import { BASE_URL } from "./config";

// const axios_api = axios.create({
//   baseURL: BASE_URL,
//   headers: {
//     "Content-Type": "application/json",
//   },
// });

// export default axios_api;


// src/api/axios.js
import { IS_DEMO } from "../api/demoConfig";
import { mockGet, mockPost, mockPut, mockDelete } from "./mockDemo";

// 실제 서버 모드까지 대비:
import axios from "axios";
const realClient = axios.create({
  baseURL: "http://localhost:8080", // 실제 서버 주소
  headers: { "Content-Type": "application/json" },
});

const axios_api = {
  get: async (path, opts = {}) => {
    if (IS_DEMO) {
      return { data: mockGet(path, opts) };
    }
    return await realClient.get(path, opts);
  },
  post: async (path, body, opts = {}) => {
    if (IS_DEMO) {
      return { data: mockPost(path, body, opts) };
    }
    return await realClient.post(path, body, opts);
  },
  put: async (path, body, opts = {}) => {
    if (IS_DEMO) {
      return { data: mockPut(path, body, opts) };
    }
    return await realClient.put(path, body, opts);
  },
  delete: async (path, opts = {}) => {
    if (IS_DEMO) {
      return { data: mockDelete(path, opts) };
    }
    return await realClient.delete(path, opts);
  },
};

export default axios_api;
